begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select pg_advisory_xact_lock(hashtextextended('debug-duel:engine-tick',0));
create temp table engine_test_results(line text);
create temp table engine_test_data(name text primary key,value jsonb);
grant all on engine_test_results,engine_test_data to anon,authenticated;
grant usage on schema extensions to anon,authenticated;
update private.engine_health set last_successful_tick_at=clock_timestamp(),last_gap_at=null where id;
create function pg_temp.engine_actor(n integer) returns uuid language sql immutable as $$select ('f6000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.engine_cmd(n integer,action text,mid uuid default null,rid uuid default null,line integer default null,ready boolean default null,key uuid default gen_random_uuid(),hash text default null) returns jsonb language plpgsql security invoker as $$
declare result jsonb;
begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.engine_actor(n),'role','authenticated')::text,true);
 set local role authenticated;
 result:=public.match_command(action,mid,key,ready,rid,line,hash,case when action in ('create','invite') then encode(convert_to('opaque-test-cipher','UTF8'),'base64') else null end);
 reset role;
 return result;
exception when others then reset role; raise;
end $$;
create function pg_temp.engine_room(a integer default 1,b integer default 2) returns uuid language plpgsql security invoker as $$
declare mid uuid; h text:=encode(sha256(convert_to(gen_random_uuid()::text,'UTF8')),'hex');
begin
 update private.engine_health set last_successful_tick_at=clock_timestamp(),last_gap_at=null where id;
 delete from private.rate_limits where subject_hash in (encode(sha256(convert_to('match:'||pg_temp.engine_actor(a)::text,'UTF8')),'hex'),encode(sha256(convert_to('match:'||pg_temp.engine_actor(b)::text,'UTF8')),'hex'));
 mid:=(pg_temp.engine_cmd(a,'create',hash=>h)->>'matchId')::uuid;
 perform pg_temp.engine_cmd(b,'join',hash=>h);
 perform pg_temp.engine_cmd(a,'ready',mid,ready=>true);
 perform pg_temp.engine_cmd(b,'ready',mid,ready=>true);
 return mid;
end $$;
create function pg_temp.engine_active(mid uuid,n integer,elapsed integer default 1000) returns uuid language plpgsql security invoker as $$
declare rid uuid; start_time timestamptz:=clock_timestamp()-elapsed*interval '1 millisecond';
begin
 select id into rid from public.match_rounds where match_id=mid and round_number=n;
 update public.match_rounds set starts_at=start_time,ends_at=start_time+interval '45 seconds' where id=rid;
 update private.engine_health set last_successful_tick_at=clock_timestamp(),last_gap_at=null where id;
 perform pg_temp.engine_cmd(1,'sync',mid);
 return rid;
end $$;
set local role anon;
reset role;
update private.engine_health set last_successful_tick_at=clock_timestamp()-interval '6 seconds' where id;
update private.engine_health set last_successful_tick_at=clock_timestamp(),last_gap_at=null where id;
-- The host may ready before the guest joins. Joining must not clear a live host.
select pg_temp.engine_cmd(1,'ready',(select (value->>'matchId')::uuid from engine_test_data where name='prejoin'),ready=>true);
select pg_temp.engine_cmd(2,'join',hash=>repeat('e',64));
select pg_temp.engine_cmd(1,'leave',(select (value->>'matchId')::uuid from engine_test_data where name='prejoin'));
-- A stale host still needs to confirm readiness again, even if a guest just joined.
select pg_temp.engine_cmd(1,'ready',(select (value->>'matchId')::uuid from engine_test_data where name='stalejoin'),ready=>true);
update public.match_players set last_seen_at=clock_timestamp()-interval '16 seconds' where match_id=(select (value->>'matchId')::uuid from engine_test_data where name='stalejoin');
select pg_temp.engine_cmd(2,'join',hash=>repeat('d',64));
select pg_temp.engine_cmd(1,'leave',(select (value->>'matchId')::uuid from engine_test_data where name='stalejoin'));
select pg_temp.engine_cmd(1,'answer',(select (value->>'id')::uuid from engine_test_data where name='room'),(select (value->>'id')::uuid from engine_test_data where name='round'),(case when (select correct_line from private.round_questions where round_id=(select (value->>'id')::uuid from engine_test_data where name='round'))=1 then 2 else 1 end),key=>'a6000000-0000-4000-8000-000000000001');
select pg_temp.engine_cmd(2,'answer',(select (value->>'id')::uuid from engine_test_data where name='room'),(select (value->>'id')::uuid from engine_test_data where name='round'),(select correct_line from private.round_questions where round_id=(select (value->>'id')::uuid from engine_test_data where name='round')),key=>'a6000000-0000-4000-8000-000000000002');
update public.match_rounds set starts_at=clock_timestamp()+interval '2 seconds',ends_at=clock_timestamp()+interval '47 seconds' where false;
with t as (select clock_timestamp() as v) update public.match_rounds set starts_at=t.v+interval '2 seconds',ends_at=t.v+interval '47 seconds' from t where match_id=(select (value->>'id')::uuid from engine_test_data where name='room') and round_number=2;
select pg_temp.engine_cmd(1,'answer',(select (value->>'id')::uuid from engine_test_data where name='room'),(select (value->>'id')::uuid from engine_test_data where name='round'),(case when (select correct_line from private.round_questions where round_id=(select (value->>'id')::uuid from engine_test_data where name='round'))=1 then 2 else 1 end));select pg_temp.engine_cmd(2,'answer',(select (value->>'id')::uuid from engine_test_data where name='room'),(select (value->>'id')::uuid from engine_test_data where name='round'),(case when (select correct_line from private.round_questions where round_id=(select (value->>'id')::uuid from engine_test_data where name='round'))=1 then 2 else 1 end));
select pg_temp.engine_cmd(1,'answer',(select (value->>'id')::uuid from engine_test_data where name='room'),(select (value->>'id')::uuid from engine_test_data where name='round'),(select correct_line from private.round_questions where round_id=(select (value->>'id')::uuid from engine_test_data where name='round')));
update public.match_players set last_seen_at=clock_timestamp()-interval '31 seconds' where match_id=(select (value->>'id')::uuid from engine_test_data where name='room') and slot=1;
update public.match_players set last_seen_at=clock_timestamp()-interval '31 seconds' where match_id=(select (value->>'id')::uuid from engine_test_data where name='room');
select private.finish_match((select (value->>'id')::uuid from engine_test_data where name='room'),pg_temp.engine_actor(1),'completed');
update public.match_players set last_seen_at=clock_timestamp()-interval '31 seconds' where match_id=(select (value->>'id')::uuid from engine_test_data where name='room');
update private.engine_health set last_successful_tick_at=clock_timestamp()-interval '11 seconds' where id;
update private.engine_health set last_successful_tick_at=clock_timestamp()-interval '11 seconds' where id;select private.advance_due_matches();
delete from private.round_questions where round_id in(select id from public.match_rounds where match_id=(select (value->>'id')::uuid from engine_test_data where name='room'));delete from public.match_rounds where match_id=(select (value->>'id')::uuid from engine_test_data where name='room');update public.matches set next_transition_at=clock_timestamp()-interval '1 second' where id=(select (value->>'id')::uuid from engine_test_data where name='room');
with t as(select clock_timestamp()-interval '1 second' v) update public.match_rounds set starts_at=t.v,ends_at=t.v+interval '45 seconds' from t where match_id=(select (value->>'id')::uuid from engine_test_data where name='good') and round_number=1; update public.matches set next_transition_at=clock_timestamp()-interval '1 second' where id=(select (value->>'id')::uuid from engine_test_data where name='good');select private.advance_due_matches();
select private.finish_match((select (value->>'id')::uuid from engine_test_data where name='good'),null,'both_disconnected');
-- Daily cleanup removes sensitive payloads without breaking idempotent expiry.
values(pg_temp.engine_actor(1),'create_match','a6000000-0000-4000-8000-000000000099',
 encode(sha256(convert_to(jsonb_build_object('action','create','match',null,'ready',null,'token',null)::text,'UTF8')),'hex'),
 jsonb_build_object('matchId',(select value->>'id' from engine_test_data where name='room')),decode('beef','hex'),clock_timestamp()-interval '1 minute',clock_timestamp()-interval '2 minutes');
with t as(select clock_timestamp()-interval '24 hours' v)
select 'c6000000-0000-4000-8000-000000000001',repeat('6',64),q.id,q.version,q.title,q.prompt,q.code,q.line_count,q.correct_line,q.explanation,q.corrected_code,t.v,t.v+interval '45 seconds',t.v+interval '24 hours'-interval '1 second'
from private.questions q,t where q.pool='practice' and q.is_active limit 1;
select private.cleanup_game_data();
select line from engine_test_results;
rollback;
